contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes parameters to exercise withdraw, withdrawAll, and sendMoney.
    // amountWithdraw: amount to pass to withdraw
    // sendTarget: recipient for sendMoney
    // sendAmount: amount to send via sendMoney
    // sendData: calldata for sendMoney
    function run(uint amountWithdraw, address payable sendTarget, uint sendAmount, bytes calldata sendData) public payable {
        require(true);

        // Ensure this contract has enough Ether to send into c for testing sends/fallbacks
        // We will fund c by calling its fallback via a low-level call from this contract
        // But since c's fallback is payable, call c with value=msg.value from the outer caller is not available here.
        // So instead, require this contract has balance to transfer to c by using sendMoney when c already has funds.
        // To create a nonzero balance in c, we forward any msg.value sent to this run to c by calling its fallback via an empty-call.
        // Note: c.fallback increments depositsCount and accepts Ether.
        if (msg.value > 0) {
            // send Ether to c to fund it
            (bool s,) = address(c).call{value: msg.value}("");
            // If this low-level call fails, the rest of the test cannot proceed meaningfully; allow revert to bubble up
            require(s);
        }

        uint beforeCBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt withdraw of an arbitrary amount. Catch revert flag.
        bool withdrewReverted;
        try c.withdraw(amountWithdraw) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint midCBalance = address(c).balance;

        // Attempt withdrawAll. Catch revert flag.
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        uint afterWithdrawAllBalance = address(c).balance;

        // Attempt sendMoney to arbitrary target with provided data and amount; catch revert
        bool sendMoneyReverted;
        // Ensure this contract has enough balance to provide sendAmount to c if needed when calling sendMoney on c we do not send value from this contract,
        // but c will itself forward funds from its balance to target, so no balance requirement here beyond c's balance.
        try c.sendMoney(sendTarget, sendAmount, sendData) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        uint finalCBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General invariant to assert:
        // - If a call succeeded (did not revert), then c's balance must have decreased by at least the amount that was requested to be transferred in that call
        //   (for withdraw: amountWithdraw; for withdrawAll: previous balance at that time; for sendMoney: sendAmount).
        // - If a call reverted, c's balance must be unchanged by that call.
        // We express this as a conjunction over the observed balances and revert flags.

        // Compute expected behaviors conservatively using the observed balances sequence.
        // from beforeCBalance -> midCBalance reflects effect of withdraw
        uint deltaAfterWithdraw = beforeCBalance >= midCBalance ? beforeCBalance - midCBalance : 0;
        // midCBalance -> afterWithdrawAllBalance reflects effect of withdrawAll
        uint deltaAfterWithdrawAll = midCBalance >= afterWithdrawAllBalance ? midCBalance - afterWithdrawAllBalance : 0;
        // afterWithdrawAllBalance -> finalCBalance reflects effect of sendMoney
        uint deltaAfterSend = afterWithdrawAllBalance >= finalCBalance ? afterWithdrawAllBalance - finalCBalance : 0;

        // For withdraw: if it reverted, delta must be 0; if it succeeded, delta must be >= amountWithdraw (but cannot exceed beforeCBalance)
        bool withdraw_ok = withdrewReverted ? (deltaAfterWithdraw == 0) : (deltaAfterWithdraw >= amountWithdraw);

        // For withdrawAll: if it reverted, delta should be 0; if it succeeded, delta should equal midCBalance (it should drain the contract at that point)
        bool withdrawAll_ok = withdrawAllReverted ? (deltaAfterWithdrawAll == 0) : (deltaAfterWithdrawAll == midCBalance);

        // For sendMoney: if it reverted, delta should be 0; if it succeeded, delta should be >= sendAmount
        bool send_ok = sendMoneyReverted ? (deltaAfterSend == 0) : (deltaAfterSend >= sendAmount);

        // Additionally, depositsCount should have increased exactly by 1 if we forwarded msg.value to c, otherwise unchanged.
        uint expectedDepositsIncrement = msg.value > 0 ? 1 : 0;
        bool deposits_ok = (afterDeposits - beforeDeposits) == expectedDepositsIncrement;

        assert(withdraw_ok && withdrawAll_ok && send_ok && deposits_ok);
    }

    // Receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amountFund: how much Ether this test will forward into c to create a positive balance
    function run(uint amountFund) public payable {
        require(address(this).balance >= amountFund);

        // Fund c by sending Ether to its fallback (payable fallback increments depositsCount)
        if (amountFund > 0) {
            (bool sent, ) = address(c).call{value: amountFund}("");
            require(sent);
        }

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Assert the general rule: if withdrawAll succeeded, c.balance is zero afterwards;
        // and in all cases depositsCount did not decrease (it may stay same or increase from our funding)
        assert((withdrewAllReverted || afterBalance == 0) && afterDeposits >= beforeDeposits);
    }

    receive() external payable {}
}

