        // If fund > 0, send Ether to c via its fallback to increase depositsCount
        if (fund > 0) {
            (bool ok, ) = address(c).call{value: fund}("");
            require(ok);
        }

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: withdrawAll either reverts, or clears the contract balance to zero;
        // additionally, depositsCount does not decrease.
        assert((withdrewAllReverted || afterBalance == 0) && afterDeposits >= beforeDeposits);
    }

    receive() external payable {}
}

