contract InvMutTest {
    C c;
    address payable owner;

    constructor(C _c) {
        c = _c;
        // record the owner as the deployer stored in c.owner()
        owner = payable(c.owner());
    }

    // This single public function tests calls from a non-owner (this contract) and from the owner (simulated by forwarding via a call).
    // Parameters:
    // - target: address to use for sendMoney target (can be any)
    // - value: amount of wei to attempt to withdraw/send
    // - data: calldata for sendMoney
    // - depositAmount: amount of wei to send to C via fallback to increase depositsCount and balance
    function run(address payable target, uint value, bytes calldata data, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "test needs funds for deposit");
        // Precondition: depositAmount can be zero; value may be any uint.

        // 1) Make a deposit into C (triggers fallback and increments depositsCount and balance)
        // Send depositAmount from this contract to C
        if (depositAmount > 0) {
            // ensure we have the funds in this contract
            (bool ok,) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

        // Read observables before attempted non-owner outgoing calls
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // 2) As InvMutTest (which is NOT owner unless owner == address(this)), attempt to call withdraw, withdrawAll, and sendMoney
        bool revert_withdraw;
        try c.withdraw(value) {
            revert_withdraw = false;
        } catch {
            revert_withdraw = true;
        }

        bool revert_withdrawAll;
        try c.withdrawAll() {
            revert_withdrawAll = false;
        } catch {
            revert_withdrawAll = true;
        }

        bool revert_sendMoney;
        try c.sendMoney(target, value, data) {
            revert_sendMoney = false;
        } catch {
            revert_sendMoney = true;
        }

        // Observables after attempts
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // If this contract is not the owner, none of these non-owner calls should succeed and balance and depositsCount must be unchanged.
        // If this contract is the owner, then at least withdraw or withdrawAll or sendMoney might succeed; we only assert the non-owner-case property.
        bool isThisOwner = (address(this) == owner);

        // General rule asserted: if caller is not owner then all three calls revert and balance and depositsCount unchanged
        assert(isThisOwner || (revert_withdraw && revert_withdrawAll && revert_sendMoney && balAfter == balBefore && depositsAfter == depositsBefore));
    }

    // Allow the test contract to receive Ether so it can forward deposits and cover value parameters
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address owner;

    constructor(C _c) {
        c = _c;
        owner = c.owner();
    }

    // Params:
    // depositAmount: amount to send to C first to ensure there is balance
    // withdrawAllAsOwner: if true, the test will try to call withdrawAll as the owner by using the owner address via low-level call emulation is NOT allowed; instead we require that this contract is the owner to exercise the owner path. To satisfy constraints, we make this contract the owner by requiring it equals c.owner().
    function run(uint depositAmount, bool withdrawAllAsOwner) public payable {
        require(address(this).balance >= depositAmount, "need funds to deposit");

        // Precondition: to test the owner behavior we require this contract to be owner when withdrawAllAsOwner==true
        require(!withdrawAllAsOwner || address(this) == owner, "to call withdrawAll as owner this contract must be owner");

        // 1) deposit Ether into c to create a balance and trigger fallback (increment depositsCount)
        if (depositAmount > 0) {
            (bool ok, ) = address(c).call{value: depositAmount}("");
            require(ok, "deposit failed");
        }

        // Observe before-values
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool revertedWithdrawAll;
        // 2) Attempt withdrawAll; if withdrawAllAsOwner is true this contract is owner and the call should execute, otherwise it should revert
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Observe after-values
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // General rule: when the owner (here possibly this contract) calls withdrawAll it empties C's balance (balAfter == 0)
        // and depositsCount does not decrease (depositsAfter >= depositsBefore).
        // If the caller is not owner then withdrawAll must revert and state unchanged w.r.t balance and depositsCount.
        bool amOwner = (address(this) == owner);

        assert( (amOwner && !revertedWithdrawAll && balAfter == 0 && depositsAfter >= depositsBefore)
                || (!amOwner && revertedWithdrawAll && balAfter == balBefore && depositsAfter == depositsBefore) );
    }

    // allow receiving Ether
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // depositAmount: amount to deposit into c first (to give it balance)
    // sendValue: amount passed to sendMoney
    // target: address to forward funds to (may be any)
    // data: calldata passed to sendMoney
    function run(uint depositAmount, uint sendValue, address target, bytes calldata data) public payable {
        require(address(this).balance >= depositAmount, "need ETH to deposit");
        // 1) deposit to c by sending ETH to its fallback to increase balance and depositsCount
        if (depositAmount > 0) {
            (bool okDeposit, ) = address(c).call{value: depositAmount}("");
            require(okDeposit, "deposit failed");
        }

        // Observe before-values via public getters / address
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        address owner = c.owner();

        // Precondition: ensure we don't try to send more than c has when owner calls sendMoney
        // (the contract's sendMoney will attempt the call and may forward more than balance causing it to fail)
        // We don't require anything here; we'll capture whether call reverted.

        bool reverted;
        // 2) attempt to call sendMoney as this contract (which is msg.sender for c calls)
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // Determine whether this contract is owner (only owner is allowed to sendMoney)
        bool amOwner = (address(this) == owner);

        // General rule:
        // - If caller is owner: call must not revert, C's balance decreases by exactly sendValue (but not below 0)
        //   (i.e., if sendValue <= balBefore then !reverted and balAfter == balBefore - sendValue),
        //   otherwise call reverts and state unchanged.
        // - If caller is not owner: call reverts and both balance and depositsCount are unchanged.

        // Encode the rule as a single assert over observed values and params.
        assert(
            // owner case: either succeeds transferring sendValue (when enough balance), or reverts if not enough
            (amOwner && (
                ((sendValue <= balBefore) && !reverted && balAfter == balBefore - sendValue && depositsAfter == depositsBefore)
                ||
                ((sendValue > balBefore) && reverted && balAfter == balBefore && depositsAfter == depositsBefore)
            ))
            // non-owner case: must revert and state unchanged
            ||
            (!amOwner && reverted && balAfter == balBefore && depositsAfter == depositsBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // depositAmount: amount this test will deposit into c via fallback (to give it balance)
    // sendValue: amount passed to c.sendMoney
    // target: address to forward funds to
    // data: calldata passed to sendMoney
    function run(uint depositAmount, uint sendValue, address target, bytes calldata data) public payable {
        // must have ether to deposit if depositAmount > 0
        require(address(this).balance >= depositAmount, "not enough ether to deposit");

        // 1) deposit to c by sending ETH to its fallback (this is a top-level state-changing external call)
        if (depositAmount > 0) {
            (bool okDeposit, ) = address(c).call{value: depositAmount}("");
            require(okDeposit, "deposit failed");
        }

        // Observe before-values
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        address owner = c.owner();

        // Attempt sendMoney as this contract (top-level state-changing call with try/catch)
        bool reverted;
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        bool amOwner = (address(this) == owner);

        // General rule (single assert):
        // - If caller is owner and sendValue <= balBefore then call must succeed, balAfter == balBefore - sendValue, deposits unchanged.
        // - If caller is owner and sendValue > balBefore then call must revert and state unchanged.
        // - If caller is not owner then call must revert and state unchanged.
        assert(
            (amOwner && ((sendValue <= balBefore && !reverted && balAfter == balBefore - sendValue && depositsAfter == depositsBefore)
                        || (sendValue > balBefore && reverted && balAfter == balBefore && depositsAfter == depositsBefore)))
            || (!amOwner && reverted && balAfter == balBefore && depositsAfter == depositsBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // depositAmount: amount to deposit into c via fallback
    // sendValue: amount to pass to c.sendMoney
    // target: address to forward funds to
    // data: calldata passed to sendMoney
    function run(uint depositAmount, uint sendValue, address target, bytes calldata data) public payable {
        // ensure this contract has enough Ether to perform the deposit if requested
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // 1) Deposit to c by sending ETH to its fallback (top-level call)
        if (depositAmount > 0) {
            (bool okDeposit, ) = address(c).call{value: depositAmount}("");
            require(okDeposit, "deposit failed");
        }

        // Observe before-values (view calls allowed inside function body)
        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        address owner = c.owner();

        // 2) Attempt sendMoney as this contract (top-level state-changing call with try/catch)
        bool reverted;
        try c.sendMoney(target, sendValue, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint balAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        bool amOwner = (address(this) == owner);

        // General rule (single assert):
        // - If caller is owner and sendMoney succeeded (did not revert) then sendValue <= balBefore,
        //   balAfter == balBefore - sendValue, deposits unchanged.
        // - Otherwise (non-owner or reverted) state is unchanged: balAfter == balBefore and deposits unchanged.
        assert(
            (amOwner && !reverted && sendValue <= balBefore && balAfter == balBefore - sendValue && depositsAfter == depositsBefore)
            || ((!amOwner || reverted) && balAfter == balBefore && depositsAfter == depositsBefore)
        );
    }

    // allow receiving ETH when c.sendMoney forwards to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether when C transfers to this contract
    receive() external payable {}

    // single public test function
    function run(address target, uint amountToSend, uint withdrawAmount, bytes calldata data) public payable {
        require(true);
        // Ensure this test contract has enough balance to forward to c when sending Ether
        if (amountToSend > 0) {
            require(address(this).balance >= amountToSend);
            // send Ether into C via its fallback by calling with value and no data
            // fallback increments depositsCount; use call to send value
            (bool ok, ) = address(c).call{value: amountToSend}("");
            require(ok);
        }

        // record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // As the owner (this contract deployed C), calls to withdraw and withdrawAll should not revert
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt a sendMoney which may revert depending on target and data; capture revert
        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Observed deltas
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // General rule asserted:
        // If withdraw or withdrawAll did not revert, then C's balance cannot have increased by that call
        // (i.e., afterCBalance <= beforeCBalance). Also depositsCount only increases via fallback (we invoked fallback only when sending with empty data), so depositsCount should be >= beforeDeposits.
        // The assert captures these relations for all inputs and outcomes.
        assert(
            // depositsCount never decreases
            afterDeposits >= beforeDeposits
            // if withdraw succeeded or withdrawAll succeeded then C's balance did not increase
            && ((withdrewReverted == false || withdrawAllReverted == false) ? (afterCBalance <= beforeCBalance) : true)
            // if withdraw succeeded then this contract's balance did not decrease because of that (it should increase or stay same)
            && (withdrewReverted == false ? (afterThisBalance >= beforeThisBalance) : true)
        );
    }
 }

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // receive Ether when C sends to this contract
    receive() external payable {}

    // Single public test function driven by inputs
    function run(address target, uint sendToC, uint withdrawAmount, bytes calldata data) public payable {
        require(true);

        // If we intend to fund C, ensure this contract has the funds and then send Ether to C via low-level call
        if (sendToC > 0) {
            require(address(this).balance >= sendToC);
            (bool ok, ) = address(c).call{value: sendToC}("");
            require(ok);
        }

        // Read observable before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // As owner (this contract deployed C), call withdraw and withdrawAll; capture reverts
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Also attempt sendMoney (may revert depending on target/data)
        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read observable after-state
        uint afterDeposits = c.depositsCount();
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // Assert the general invariant:
        // 1) depositsCount never decreases
        // 2) If withdraw or withdrawAll succeeded, C's balance did not increase as a result
        // 3) If withdraw succeeded, this contract's balance did not decrease (it should receive funds)
        assert(
            afterDeposits >= beforeDeposits
            && ((withdrewReverted == false || withdrawAllReverted == false) ? (afterCBalance <= beforeCBalance) : true)
            && (withdrewReverted == false ? (afterThisBalance >= beforeThisBalance) : true)
        );
    }
}

