        require(true);

        // If we will fund C, ensure this contract has the funds
        if (sendToC > 0) {
            require(address(this).balance >= sendToC);
            (bool okFund, ) = address(c).call{value: sendToC}("");
            require(okFund);
        }

        // observe before-state
        uint beforeDeposits = c.depositsCount();
        uint beforeCBalance = address(c).balance;

        // As owner (this contract deployed C), attempt withdraw; capture revert
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
