contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address target, uint fundC, uint withdrawAmount, bytes calldata data) public payable {
        require(true);

        // If we will fund C, ensure this contract has the funds
