            // call withdraw(uint)
            try c.withdraw{value: amountSent}(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 1) {
            // call withdrawAll()
            try c.withdrawAll{value: amountSent}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call sendMoney(address,uint,bytes)
            // ensure this contract has enough balance to forward 'amountSent' into c call
