    // times: how many separate fallback invocations to perform (as repeated low-level calls)
    // eachFund: Ether to send in each fallback invocation
    // withdrawAmt: amount to attempt to withdraw afterward
    function run(uint times, uint eachFund, uint withdrawAmt) public payable {
        // ensure this test contract has enough balance to fund the fallback calls
        require(address(this).balance >= times * eachFund);

        // Observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Perform `times` separate fallback calls, each sending `eachFund` wei.
        // Each is a top-level state-changing low-level call, not nested.
        for (uint i = 0; i < times; i++) {
            (bool ok, ) = address(c).call{value: eachFund}("");
            // we don't require success here; fallback can accept or the call can fail
            // but the effect on depositsCount should correspond to number of successful fallback invocations
            // however the contract's fallback is payable and should succeed unless out-of-gas or revert from fallback
            // keep going regardless
            ok; // silence unused variable warning pattern
        }

        // Observe after funding
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Try withdraw(uint) and record whether it reverted. This is a top-level state-changing call on c.
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Observe final balance and deposits
        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule (single assert):
        // 1) depositsCount increased by at most `times` and never decreased: finalDeposits >= beforeDeposits && (afterDeposits - beforeDeposits) <= times
        // 2) The balance increase after the fallback calls equals the sum actually sent: afterBalance >= beforeBalance and (afterBalance - beforeBalance) <= times * eachFund
        // 3) A successful withdraw cannot increase the contract's balance: if withdraw succeeded then finalBalance <= afterBalance
        assert(
            finalDeposits >= beforeDeposits
            && (afterDeposits - beforeDeposits) <= times
            && afterBalance >= beforeBalance
            && (afterBalance - beforeBalance) <= times * eachFund
            && (withdrewReverted || finalBalance <= afterBalance)
        );
    }

    // allow receiving Ether if c sends funds back
    receive() external payable {}
}

