        // to c by using c as a payable address with this contract as msg.sender: that is not a call on c's functions, but still modifies c.balance.

        // Send Ether to c directly (this triggers fallback and increases depositsCount by 1 on success)
        // This is a low-level sending from this contract to c; it's a state change of c but not via c.f(...), allowed because it's an external effect.
        (bool sentToFallback, ) = address(c).call{value: sendToFallbackAmount}(fallbackData);

        // 2) Now, attempt owner-only calls on c. Since InvMutTest deployed c, this contract is owner, so calls should succeed.
        // Call sendMoney on c to send `value` to `target` with provided data. This is a top-level state-changing call on c.
        // Ensure this contract has enough balance to fund sendMoney through c by first checking address(c).balance.
        // No require on c.balance (checker provides fresh c), but our funds were transferred above.
        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Call withdraw with 0 value as owner (should succeed and not change c.balance if _value == 0)
        bool withdrawReverted;
        try c.withdraw(0) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Call withdrawAll as owner (should succeed and transfer entire balance out, so c.balance becomes 0)
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // read after state
        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount();

        // Assert general rule:
        // - If the direct send to c succeeded, depositsCount increases exactly by 1 and c.balance increased by sendToFallbackAmount before owner withdrawals.
        // - Any successful owner withdrawAll must result in c.balance == 0 afterwards.
        // We encode a single assert combining both behaviors for all inputs.
        assert(
            (
                // Case: fallback send failed -> no change in depositsCount and no increase in balance from that send
                (!sentToFallback && afterCount == beforeCount && afterBalance <= beforeBalance + 0)
            )
            ||
            (
                // Case: fallback send succeeded -> depositsCount incremented by exactly 1
                (sentToFallback && afterCount == beforeCount + 1 && ( (
                    // If withdrawAll succeeded, c.balance must be 0
                    !withdrawAllReverted && afterBalance == 0
                ) || (
                    // If withdrawAll reverted, c.balance must be at least increased by sendToFallbackAmount minus any successful sendMoney/withdraw of value
                    // Because sendMoney may have transferred `value` out, we ensure that afterBalance <= beforeBalance + sendToFallbackAmount
                    withdrawAllReverted && afterBalance <= beforeBalance + sendToFallbackAmount
                ) )) )
            )
        );
    }

    // allow this contract to receive Ether so it can forward to c
    receive() external payable {}
}

