contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes an amount to attempt to withdraw and a flag chooseAll to call withdrawAll instead of withdraw.
    // The contract must be the owner of c (since the checker deploys a fresh C with owner = deployer, which is this test
    // contract). We will try both withdraw and withdrawAll as requested.
    function run(uint withdrawAmount, bool chooseAll) public payable {
        // ensure this contract has enough balance to fund deposits into c if desired
        // We don't require any particular precondition on parameters
        // First, make the contract hold some Ether and send a deposit via fallback to increase depositsCount
        // To be able to send Ether to c we require balance here >= 1 when calling with value.
        // If this transaction provided Ether (msg.value), it is available to this contract; otherwise the checker
        // may supply no Ether, so we won't try to send if balance insufficient.

        // Record initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Optionally send a small deposit to trigger fallback and increase depositsCount if we have funds
        if (address(this).balance >= 1 wei) {
            // top-level state-changing call
            c.f{value: 1 wei}();
        }

        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Now attempt the withdrawal. We try withdrawAll when chooseAll==true, otherwise withdraw(withdrawAmount).
        bool reverted;
        if (chooseAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // - depositsCount is only affected by fallback (we only possibly triggered fallback above), so withdrawals must not change depositsCount: afterDeposits == midDeposits
        // - If the withdrawal reverted then balance must be unchanged: reverted => afterBalance == midBalance
        // - If the withdrawal succeeded then afterBalance + withdrawnAmount >= midBalance - (amount attempted), i.e. balance decreased by at most the attempted withdraw.
        //   For withdrawAll we observe that afterBalance == 0 or revert; to keep a general inequality: midBalance - afterBalance <= withdrawAmount OR (chooseAll && midBalance - afterBalance <= midBalance)

        // We express the succeeded case conservatively with inequalities avoiding underflow.
        bool succeeded = !reverted;

        // compute intended max decrease: for withdrawAll it's midBalance, for withdraw it's withdrawAmount
        uint intendedMaxDecrease = chooseAll ? midBalance : withdrawAmount;

        // Condition parts
        bool depositsUnchanged = (afterDeposits == midDeposits);
        bool revertLeavesBalance = (!succeeded) ? (afterBalance == midBalance) : true;
        bool successRespectsMaxDecrease = succeeded ? (midBalance >= afterBalance && (midBalance - afterBalance) <= intendedMaxDecrease) : true;

        assert(depositsUnchanged && revertLeavesBalance && successRespectsMaxDecrease);
    }

    // Allow receiving Ether so this test contract may hold funds used to send to c
    receive() external payable {}
    fallback() external payable {}
}

