contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an amount to deposit into C (forwarded via this contract) and then call withdrawAll as owner.
    // To be owner of C this test contract must be the deployer passed to constructor by the harness.
    function run(uint256 depositAmount) public payable {
        // Ensure this test contract has enough balance to fund the deposit to C
        require(address(this).balance >= depositAmount);

        // record before-values
        uint256 beforeCount = c.depositsCount();
        uint256 beforeBal = address(c).balance;

        // make a payable call to C to trigger fallback and deposit Ether (top-level state-changing call)
        c.f{value: depositAmount}();

        // read intermediate values after deposit
        uint256 midCount = c.depositsCount();
        uint256 midBal = address(c).balance;

        // Only proceed to withdrawAll if this contract is owner — otherwise withdrawAll would revert.
        // We cannot call c.owner() directly inside a require that blocks execution of the top-level calls
        // (reads are allowed), so check ownership now.
        address owner = c.owner();
        bool amOwner = (owner == address(this));

        bool didRevert;
        if (amOwner) {
            // call withdrawAll as owner (top-level state-changing call)
            try c.withdrawAll() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // if not owner, we still set didRevert = true to reflect that withdrawAll cannot succeed
            didRevert = true;
        }

        uint256 afterCount = c.depositsCount();
        uint256 afterBal = address(c).balance;

        // General rule: If this contract is the owner and withdrawAll did not revert, then afterBal == 0
        // and depositsCount is unchanged by withdrawAll (i.e., afterCount == midCount).
        // If not owner or withdrawAll reverted, then balances/counts are unchanged by the attempted withdraw.
        assert(
            amOwner
                ? (!didRevert ? (afterBal == 0 && afterCount == midCount) : (afterBal == midBal && afterCount == midCount))
                : (afterBal == midBal && afterCount == midCount)
        );
    }

    // allow receiving ETH so this test contract can fund calls
    receive() external payable {}
}
